26	/// Camera block demo. Move a red circle inside a boundary rectangle with WASD/arrows;
27	/// switch between five fixed camera targets (numbered 1–5, each shown as a hoverable
28	/// region in the world) and a follow mode (key 0). The "smooth lerp" toggle controls
29	/// the damping on <see cref="CameraFollowTargetComponent"/>: when on, the camera eases
30	/// toward its target (ball in follow mode, or the corresponding zone center in fixed
31	/// modes); when off, it snaps instantly.
32	///
33	/// In follow mode the camera also zooms out a little as its center lags behind the
34	/// red dot — see <see cref="CameraLagZoomSystem"/>. The more the dot outruns the
35	/// camera (fast moves, or pushing into the camera-bounds edges), the wider the view.
36	public class CameraDemoScreen : IGameScreen
37	{
38	    private const float BoundaryHalfWidth = 380f;
39	    private const float BoundaryHalfHeight = 220f;
40	    // Camera-movement bounds in follow mode — a little smaller than the boundary,
41	    // so the red dot can push past the camera's reach toward the screen edges.
42	    private const float CameraBoundsHalfWidth = 280f;
43	    private const float CameraBoundsHalfHeight = 140f;
44	    private const float ZoneSize = 80f;
45	    private const float BallRadius = 20f;
46	    private const float MoveSpeed = 240f;
47	
48	    private const float DampingSmooth = 5f;
49	    private const float DampingInstant = 100f;
50	
51	    /// Keyboard-key 0..5 maps directly to enum index: 0 Follow, 1 TL, 2 TR,
52	    /// 3 BR, 4 BL, 5 Center. Reordering is intentional — clockwise around the
53	    /// boundary corners with Center last.
54	    public enum Mode { Follow, FixedTL, FixedTR, FixedBR, FixedBL, FixedCenter }
55	
56	    private readonly ContentManager _content;
57	    private readonly GraphicsDevice _graphicsDevice;
58	    private readonly MonoDreams.Component.Camera _camera;
59	    private readonly ViewportManager _viewportManager;
60	    private readonly SpriteBatch _spriteBatch;
61	    private readonly World _world;
62	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
63	    private readonly BitmapFont _font;
64	
65	    private ScreenController? _screenController;
66	    private Entity _ball;
67	    private Entity _cameraAnchor;
68	    private Entity _lerpToggle;
69	    private Entity _targetCross;
70	    private Entity _cameraBoundsRect;
71	    private Mode _mode = Mode.Follow;
72	    private bool _lerpSmooth = true;
73	
74	    private readonly Dictionary<Mode, Entity> _sidebarButtons = new();
75	    private readonly Dictionary<Mode, Entity> _worldZoneButtons = new();
