104	    public void Load(ScreenController screenController, ContentManager content)
105	    {
106	        _screenController = screenController;
107	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
108	
109	        var cursorTextures = new Dictionary<CursorType, Texture2D>
110	        {
111	            [CursorType.Default] = content.Load<Texture2D>("Cursor/default"),
112	            [CursorType.Pointer] = content.Load<Texture2D>("Cursor/pointer"),
113	            [CursorType.Hand] = content.Load<Texture2D>("Cursor/hand"),
114	        };
115	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
116	
117	        _cameraAnchor = _world.CreateEntity();
118	        _cameraAnchor.Set(new TransformComponent(Vector2.Zero));
119	
120	        CreateBoundary();
121	        CreateCameraBoundsRect();
122	        CreateWorldZones();
123	        CreateBall();
124	        CreateTargetCross();
125	        CreateCameraCenterCross();
126	        BuildHud(content);
