131	    // ─── public bridges for the keyboard system ───────────────────────────────
132	
133	    public void SetMode(Mode mode)
134	    {
135	        _mode = mode;
136	        foreach (var (m, btn) in _sidebarButtons) UpdateActive(btn, m == mode);
137	        foreach (var (m, btn) in _worldZoneButtons) UpdateActive(btn, m == mode);
138	
139	        // The dashed camera-bounds guide only makes sense while the camera tracks
140	        // the red dot — show it in follow mode, hide it in the fixed modes.
141	        SetCameraBoundsVisible(mode == Mode.Follow);
142	
143	        if (mode == Mode.Follow)
144	        {
145	            if (_cameraAnchor.Has<CameraFollowTargetComponent>())
146	                _cameraAnchor.Remove<CameraFollowTargetComponent>();
147	            if (!_ball.Has<CameraFollowTargetComponent>())
148	                _ball.Set(new CameraFollowTargetComponent());
149	            ApplyDampingTo(_ball);
150	            _ball.Get<CameraFollowTargetComponent>().Bounds = CameraBounds();
151	            ReparentTargetCross(_ball);
152	        }
153	        else
154	        {
155	            if (_ball.Has<CameraFollowTargetComponent>())
156	                _ball.Remove<CameraFollowTargetComponent>();
157	            var anchorTransform = _cameraAnchor.Get<TransformComponent>();
158	            anchorTransform.Position = ModeCameraTarget(mode);
159	            if (!_cameraAnchor.Has<CameraFollowTargetComponent>())
160	                _cameraAnchor.Set(new CameraFollowTargetComponent());
161	            ApplyDampingTo(_cameraAnchor);
162	            ReparentTargetCross(_cameraAnchor);
163	
164	            if (!_lerpSmooth) _camera.Position = anchorTransform.Position;
165	        }
166	    }
167	
168	    private void ReparentTargetCross(Entity newParent)
169	    {
170	        if (!_targetCross.IsAlive) return;
171	        // SetParent overwrites ChildOfComponent + transform.Parent in place;
172	        // we deliberately skip RemoveParent so the cross's LOCAL position stays
173	        // at (0,0). RemoveParent snapshots the current world position into the
174	        // local one, which would double the offset on the next reparent.
175	        _targetCross.SetParent(newParent);
176	        _targetCross.Get<TransformComponent>().Position = Vector2.Zero;
177	    }
178	
179	    public void GoBackToLauncher() => _screenController?.LoadScreen(DemoScreens.Launcher);
180	
181	    public void ToggleLerp()
182	    {
183	        if (!_lerpToggle.IsAlive || !_lerpToggle.Has<ToggleSwitchComponent>()) return;
184	        var sw = _lerpToggle.Get<ToggleSwitchComponent>();
185	        sw.On = !sw.On;
186	        _lerpSmooth = sw.On;
187	        _lerpToggle.Set(sw);
188	
189	        if (_ball.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_ball);
190	        if (_cameraAnchor.Has<CameraFollowTargetComponent>())
191	        {
192	            ApplyDampingTo(_cameraAnchor);
193	            if (!_lerpSmooth) _camera.Position = _cameraAnchor.Get<TransformComponent>().Position;
194	        }
195	    }
196	
197	    private void ApplyDampingTo(Entity target)
198	    {
199	        if (!target.Has<CameraFollowTargetComponent>()) return;
200	        var ft = target.Get<CameraFollowTargetComponent>();
201	        ft.DampingX = _lerpSmooth ? DampingSmooth : DampingInstant;
202	        ft.DampingY = _lerpSmooth ? DampingSmooth : DampingInstant;
203	        ft.MaxDistanceX = 10000f;
204	        ft.MaxDistanceY = 10000f;
205	    }
