207	    private static void UpdateActive(Entity entity, bool active)
208	    {
209	        if (!entity.IsAlive || !entity.Has<DemoButtonComponent>()) return;
210	        ref var b = ref entity.Get<DemoButtonComponent>();
211	        b.IsActive = active;
212	    }
