214	    // Camera centers exactly on the zone the user clicked. Zone centers sit at the
215	    // corners offset by half the zone size so the zone sprite is fully on-screen.
216	    private static Vector2 ModeCameraTarget(Mode m)
217	    {
218	        var halfZone = ZoneSize / 2f;
219	        return m switch
220	        {
221	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth + halfZone, -BoundaryHalfHeight + halfZone),
222	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - halfZone, -BoundaryHalfHeight + halfZone),
223	            Mode.FixedCenter => Vector2.Zero,
224	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth + halfZone,  BoundaryHalfHeight - halfZone),
225	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - halfZone,  BoundaryHalfHeight - halfZone),
226	            _                => Vector2.Zero,
227	        };
228	    }
229	
230	    private static Vector2 ZoneTopLeft(Mode m)
231	    {
232	        var half = ZoneSize / 2f;
233	        return m switch
234	        {
235	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth,             -BoundaryHalfHeight),
236	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - ZoneSize,  -BoundaryHalfHeight),
237	            Mode.FixedCenter => new Vector2(-half, -half),
238	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth,              BoundaryHalfHeight - ZoneSize),
239	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - ZoneSize,   BoundaryHalfHeight - ZoneSize),
240	            _ => Vector2.Zero,
241	        };
242	    }
