244	    // ─── button click routing ────────────────────────────────────────────────
245	
246	    private void OnButtonClicked(in DemoButtonClicked msg)
247	    {
248	        switch (msg.Id)
249	        {
250	            case DemoHeader.BackId: _screenController?.LoadScreen(DemoScreens.Launcher); break;
251	            case DemoHeader.ExitId: _screenController?.Game.Exit(); break;
252	            case "mode.follow": SetMode(Mode.Follow); break;
253	            case "mode.tl":     SetMode(Mode.FixedTL); break;
254	            case "mode.tr":     SetMode(Mode.FixedTR); break;
255	            case "mode.center": SetMode(Mode.FixedCenter); break;
256	            case "mode.bl":     SetMode(Mode.FixedBL); break;
257	            case "mode.br":     SetMode(Mode.FixedBR); break;
258	            case "toggle.lerp": ToggleLerp(); break;
259	        }
260	    }
