264	    private void CreateBoundary()
265	    {
266	        var bounds = new Rectangle(
267	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
268	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
269	
270	        var boundary = _world.CreateEntity();
271	        boundary.Set(new TransformComponent(Vector2.Zero));
272	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
273	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
274	        boundary.Set(draw);
275	        boundary.Set<VisibleComponent>();
276	    }
277	
278	    /// World-space rectangle the camera position is clamped to in follow mode.
279	    private static Rectangle CameraBounds() => new(
280	        -(int)CameraBoundsHalfWidth, -(int)CameraBoundsHalfHeight,
281	        (int)CameraBoundsHalfWidth * 2, (int)CameraBoundsHalfHeight * 2);
282	
283	    /// Soft-yellow dashed guide showing how far the camera can travel in follow
284	    /// mode. Created once; its visibility is toggled by <see cref="SetMode"/> so it
285	    /// only appears while the red dot is the camera target.
286	    private void CreateCameraBoundsRect()
287	    {
288	        _cameraBoundsRect = _world.CreateEntity();
289	        _cameraBoundsRect.Set(new TransformComponent(Vector2.Zero));
290	        // 0.25 sits just above the solid boundary outline (0.2) and below the
291	        // world-zone outlines, ball, and crosses.
292	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.25f };
293	        draw.SetMeshData(new DashedRectangleOutlineMeshGenerator(
294	            CameraBounds(), thickness: 2f, color: SproutPalette.SoftYellow, dashLength: 14f, gapLength: 9f));
295	        _cameraBoundsRect.Set(draw);
296	        // VisibleComponent is added/removed by SetCameraBoundsVisible — no
297	        // CullingSystem runs in this demo, so the tag fully controls visibility.
298	    }
299	
300	    private void SetCameraBoundsVisible(bool visible)
301	    {
302	        if (!_cameraBoundsRect.IsAlive) return;
303	        if (visible && !_cameraBoundsRect.Has<VisibleComponent>())
304	            _cameraBoundsRect.Set<VisibleComponent>();
305	        else if (!visible && _cameraBoundsRect.Has<VisibleComponent>())
306	            _cameraBoundsRect.Remove<VisibleComponent>();
307	    }
