309	    private void CreateWorldZones()
310	    {
311	        // Numbering matches the keyboard digits — 1 TL, 2 TR, 3 BR, 4 BL, 5 Center.
312	        CreateWorldZone(Mode.FixedTL,     "1", "mode.tl");
313	        CreateWorldZone(Mode.FixedTR,     "2", "mode.tr");
314	        CreateWorldZone(Mode.FixedBR,     "3", "mode.br");
315	        CreateWorldZone(Mode.FixedBL,     "4", "mode.bl");
316	        CreateWorldZone(Mode.FixedCenter, "5", "mode.center");
317	    }
