319	    private void CreateWorldZone(Mode mode, string label, string id)
320	    {
321	        var topLeft = ZoneTopLeft(mode);
322	        var sharedTransform = new TransformComponent(topLeft);
323	
324	        var container = _world.CreateEntity();
325	        container.Set(sharedTransform);
326	
327	        const float labelScale = 0.50f;
328	        var measured = _font.MeasureString(label);
329	        var labelSize = new Vector2(measured.Width * labelScale, measured.Height * labelScale);
330	        var labelOffset = new Vector2((ZoneSize - labelSize.X) / 2f, (ZoneSize - labelSize.Y) / 2f);
331	        var labelEntity = _world.CreateEntity();
332	        labelEntity.Set(new TransformComponent(labelOffset));
333	        labelEntity.SetParent(container);
334	        labelEntity.Set(new DynamicTextComponent
335	        {
336	            Target = RenderTargetID.Main,
337	            LayerDepth = 0.35f,
338	            TextContent = label,
339	            Font = _font,
340	            Color = SproutPalette.TextLight,
341	            Scale = labelScale,
342	            IsRevealed = true,
343	            VisibleCharacterCount = int.MaxValue,
344	        });
345	        labelEntity.Set<VisibleComponent>();
346	
347	        var outline = _world.CreateEntity();
348	        outline.Set(sharedTransform);
349	        outline.Set(new SimpleButtonComponent
350	        {
351	            Size = new Vector2(ZoneSize, ZoneSize),
352	            LineThickness = 1.5f,
353	            Color = SproutPalette.TextLight,
354	            TextEntity = labelEntity,
355	            Target = RenderTargetID.Main,
356	        });
357	        outline.Set(new DemoButtonComponent
358	        {
359	            Id = id,
360	            DefaultColor = SproutPalette.TextLight,
361	            HoveredColor = SproutPalette.TextHover,
362	            ActiveColor = SproutPalette.TextSelected,
363	        });
364	        outline.Set<VisibleComponent>();
365	        _worldZoneButtons[mode] = outline;
366	    }
