368	    private void CreateBall()
369	    {
370	        _ball = _world.CreateEntity();
371	        _ball.Set(new TransformComponent(Vector2.Zero));
372	        _ball.Set(new PlayerBallTag());
373	        // 0.97 puts the ball above the world-zone button outlines (those get
374	        // LayerDepth=0.95 from ButtonMeshPrepSystem) so the ball doesn't get
375	        // clipped by a zone's outline as it crosses through.
376	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.97f };
377	        draw.SetMeshData(new CircleMeshGenerator(Vector2.Zero, BallRadius, SproutPalette.Crimson, segments: 32));
378	        _ball.Set(draw);
379	        _ball.Set<VisibleComponent>();
380	
381	        // Clickable hit-area for the ball — child entity offset to the ball's
382	        // top-left so the bounds-based hit test wraps the circle. Clicking the
383	        // ball switches to follow mode.
384	        var hitArea = _world.CreateEntity();
385	        hitArea.Set(new TransformComponent(new Vector2(-BallRadius, -BallRadius)));
386	        hitArea.SetParent(_ball);
387	        hitArea.Set(new SimpleButtonComponent
388	        {
389	            Size = new Vector2(BallRadius * 2, BallRadius * 2),
390	            LineThickness = 0f,
391	            Color = Color.Transparent,
392	            FillColor = Color.Transparent,
393	            TextEntity = null,
394	            Target = RenderTargetID.Main,
395	        });
396	        hitArea.Set(new DemoButtonComponent
397	        {
398	            Id = "mode.follow",
399	            DefaultColor = Color.Transparent,
400	            HoveredColor = Color.Transparent,
401	            ActiveColor = Color.Transparent,
402	        });
403	        hitArea.Set<VisibleComponent>();
404	    }
405	
406	    /// Green cross marking where the camera *wants* to be. Parented to whichever
407	    /// entity currently has <see cref="CameraFollowTargetComponent"/> so it sits
408	    /// exactly at the target — when the camera lerps, the green cross stays put
409	    /// and the screen-center yellow cross drifts toward it.
410	    private void CreateTargetCross()
411	    {
412	        _targetCross = _world.CreateEntity();
413	        _targetCross.Set(new TransformComponent(Vector2.Zero));
414	        // 0.98 puts the cross above the ball (0.97) so the target marker is
415	        // never occluded when it sits on the ball in follow mode.
416	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.98f };
417	        draw.SetMeshData(CrossMesh(armPixels: 16, thicknessPixels: 3, color: Color.Black));
418	        _targetCross.Set(draw);
419	        _targetCross.Set<VisibleComponent>();
420	    }
421	
422	    /// Yellow cross drawn on HUD at the screen center — marks the point the
423	    /// camera is currently looking at. Camera-independent (HUD is not affected
424	    /// by the view transform), so this stays put even as the world scrolls.
425	    private void CreateCameraCenterCross()
426	    {
427	        var entity = _world.CreateEntity();
428	        entity.Set(new TransformComponent(new Vector2(
429	            _viewportManager.VirtualWidth / 2f,
430	            _viewportManager.VirtualHeight / 2f)));
431	        var draw = new DrawComponent { Target = RenderTargetID.HUD, LayerDepth = 0.92f };
432	        draw.SetMeshData(CrossMesh(armPixels: 14, thicknessPixels: 3, color: Color.White));
433	        entity.Set(draw);
434	        entity.Set<VisibleComponent>();
435	    }
436	
437	    private static CompositeMeshGenerator CrossMesh(int armPixels, int thicknessPixels, Color color)
438	    {
439	        var halfT = thicknessPixels / 2;
440	        return new CompositeMeshGenerator()
441	            .Add(new FilledRectangleMeshGenerator(
442	                new Rectangle(-armPixels, -halfT, armPixels * 2, thicknessPixels), color))
443	            .Add(new FilledRectangleMeshGenerator(
444	                new Rectangle(-halfT, -armPixels, thicknessPixels, armPixels * 2), color));
445	    }
