449	    private void BuildHud(ContentManager content)
450	    {
451	        var squareButtons = content.Load<Texture2D>("SproutLands/Buttons/square_26x26");
452	        var settingsSheet = content.Load<Texture2D>("SproutLands/Buttons/settings_buttons");
