466	
467	    private void BuildSidebar(Texture2D squareButtons, Texture2D settingsSheet)
468	    {
469	        var capStyle = new KeyCapStyle
470	        {
471	            SpriteSheet = squareButtons,
472	            DefaultSource = SproutSquareButtons.CreamLight,
473	            HoverSource   = SproutSquareButtons.CreamDark,
474	            ActiveSource  = SproutSquareButtons.TanDark,
475	            // 42 matches the lerp toggle pill width so all sidebar elements
476	            // line up on a shared left edge.
477	            CapPixels = 42,
478	            CapLabelScale = 0.22f,
479	            CapLabelColor = SproutPalette.WarmBrown,
480	        };
481	        var rowStyle = new KeyRowStyle
482	        {
483	            LabelColor = SproutPalette.TextLight,
484	            HoverColor = SproutPalette.TextHover,
485	            ActiveColor = SproutPalette.TextSelected,
486	            LabelScale = 0.18f,
487	            Gap = 10f,
488	            BackgroundColor = SproutPalette.DarkBgSecondary,
489	            HoverBackgroundColor = SproutPalette.DarkBgSecondary,
490	            ActiveBackgroundColor = SproutPalette.DarkBgSecondary,
491	            BackgroundPaddingX = 10f,
492	            BackgroundPaddingY = 6f,
493	        };
494	
495	        (Entity Container, Entity Outline, Vector2 Size) Row(string id, string key, string label) =>
496	            _world.CreateKeyRow(id, key, label, _font, capStyle, rowStyle, layerDepth: 0.96f);
497	
498	        // Order: 0 follow, 1 TL, 2 TR, 3 BR, 4 BL, 5 center.
499	        var follow = Row("mode.follow", "0", "follow red dot");
500	        var tl     = Row("mode.tl",     "1", "top-left");
501	        var tr     = Row("mode.tr",     "2", "top-right");
502	        var br     = Row("mode.br",     "3", "bottom-right");
503	        var bl     = Row("mode.bl",     "4", "bottom-left");
504	        var center = Row("mode.center", "5", "center");
505	
506	        // Toggle pill native is 28x18 (aspect ~1.56). Draw at 42x27 = native × 1.5
507	        // so the aspect ratio is preserved and the pill scales to match the cap chip.
508	        var lerp = _world.CreateToggleRow(
509	            id: "toggle.lerp",
510	            rowLabel: "smooth lerp",
511	            font: _font,
512	            toggleSheet: settingsSheet,
513	            offSource: SproutSettings.ToggleOff,
514	            onSource: SproutSettings.ToggleOn,
515	            initiallyOn: _lerpSmooth,
516	            toggleSize: new Vector2(42, 27),
517	            row: rowStyle,
518	            layerDepth: 0.96f);
519	
520	        _sidebarButtons[Mode.Follow]      = follow.Outline;
521	        _sidebarButtons[Mode.FixedTL]     = tl.Outline;
522	        _sidebarButtons[Mode.FixedTR]     = tr.Outline;
523	        _sidebarButtons[Mode.FixedBR]     = br.Outline;
524	        _sidebarButtons[Mode.FixedBL]     = bl.Outline;
525	        _sidebarButtons[Mode.FixedCenter] = center.Outline;
526	        _lerpToggle = lerp.Outline;
527	
528	        const float rowGap = 6f;       // gap BETWEEN per-row backgrounds
529	        const float groupGap = 16f;    // larger gap before the lerp toggle group
530	
531	        new AutoLayoutBuilder(_world, _viewportManager)
532	            .CreateRoot(ScreenAnchor.TopLeft, RenderTargetID.HUD)
533	            .Direction(LayoutDirection.Vertical)
534	            .Gap(rowGap)
535	            // Screen-root stacks roots vertically, so the sidebar already lands
536	            // below the header automatically — just add a small breathing pad.
537	            .Padding(20 /* top */, 12 /* right */, 12 /* bottom */, 12 /* left */)
538	            .AlignCross(CrossAxisAlignment.Start)
539	            .AddSlot(slot => slot.Attach(follow.Container).MeasureWith(_ => follow.Size))
540	            .AddSlot(slot => slot.Attach(tl.Container).MeasureWith(_ => tl.Size))
541	            .AddSlot(slot => slot.Attach(tr.Container).MeasureWith(_ => tr.Size))
542	            .AddSlot(slot => slot.Attach(br.Container).MeasureWith(_ => br.Size))
543	            .AddSlot(slot => slot.Attach(bl.Container).MeasureWith(_ => bl.Size))
544	            .AddSlot(slot => slot.Attach(center.Container).MeasureWith(_ => center.Size))
545	            .AddSlot(slot => slot.Attach(_world.CreateEntity()).MeasureWith(_ => new Vector2(0, groupGap - rowGap)))
546	            .AddSlot(slot => slot.Attach(lerp.Container).MeasureWith(_ => lerp.Size))
547	            .Build();
548	    }
549	
550	    // ─── pipeline ────────────────────────────────────────────────────────────
551	
552	    private SequentialSystem<GameState> CreateUpdateSystem()
553	    {
554	        return new SequentialSystem<GameState>(
555	            new CursorInputSystem(_world),
556	            new IntrinsicSizingSystem(_world),
557	            new AutoLayoutSystem(_world, _viewportManager),
558	            new DemoButtonInteractionSystem(_world),
559	            new DemoIconRecolorSystem(_world),
560	            new ToggleSwitchSystem(_world),
561	            new PlayerBallMovementSystem(_world, BoundaryHalfWidth, BoundaryHalfHeight, BallRadius, MoveSpeed),
562	            new CameraDemoInputSystem(this),
563	            new CameraFollowSystem(_world, _camera),
564	            // Runs after the follow system so it reads this frame's resolved
565	            // camera position when measuring the lag behind the red dot.
566	            new CameraLagZoomSystem(_world, _camera),
567	            new HierarchySystem(_world),
568	            new CursorPositionSystem(_world, _camera, _viewportManager),
569	            new CursorDrawPrepSystem(_world));
570	    }
571	
572	    private SequentialSystem<GameState> CreateDrawSystem()
573	    {
574	        return new SequentialSystem<GameState>(
575	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
576	            new TextPrepSystem(_world, pixelPerfectRendering: false),
577	            new MeshPrepSystem(_world),
578	            new ButtonMeshPrepSystem(_world),
579	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _camera, _renderTargets, _world),
580	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, _camera, _renderTargets));
581	    }
582	
583	    public void Dispose()
584	    {
585	        UpdateSystem.Dispose();
586	        DrawSystem.Dispose();
587	        foreach (var rt in _renderTargets.Values) rt.Dispose();
588	        _world.Dispose();
589	        GC.SuppressFinalize(this);
590	    }
591	}
592	
593	/// Tag identifying the player-controlled circle in the camera demo.
594	public struct PlayerBallTag { }
595	
596	/// Reads keyboard input (WASD + arrows) and translates the tagged player entity,
597	/// clamping its position so the ball stays inside the boundary rectangle.
598	[With(typeof(PlayerBallTag), typeof(TransformComponent))]
599	public class PlayerBallMovementSystem : AEntitySetSystem<GameState>
600	{
601	    private readonly float _halfWidth;
602	    private readonly float _halfHeight;
603	    private readonly float _radius;
604	    private readonly float _speed;
605	
606	    public PlayerBallMovementSystem(World world, float halfWidth, float halfHeight, float radius, float speed)
607	        : base(world)
608	    {
609	        _halfWidth = halfWidth;
610	        _halfHeight = halfHeight;
611	        _radius = radius;
612	        _speed = speed;
613	    }
614	
615	    protected override void Update(GameState state, in Entity entity)
616	    {
617	        var keyboard = Keyboard.GetState();
618	        var dir = Vector2.Zero;
619	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left))  dir.X -= 1f;
620	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
621	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up))    dir.Y -= 1f;
622	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down))  dir.Y += 1f;
623	        if (dir != Vector2.Zero) dir.Normalize();
624	
625	        var transform = entity.Get<TransformComponent>();
626	        var next = transform.Position + dir * _speed * state.Time;
627	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _radius, _halfWidth - _radius);
628	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _radius, _halfHeight - _radius);
629	        transform.Position = next;
630	    }
631	}
632	
633	/// Polls the keyboard for camera-mode shortcuts (0–5, L) and forwards them
634	/// to the owning <see cref="CameraDemoScreen"/>. Edge-triggered: each key press
635	/// fires once per release-then-press cycle.
636	public class CameraDemoInputSystem : ISystem<GameState>
637	{
638	    private readonly CameraDemoScreen _screen;
639	    private KeyboardState _previous;
640	    public bool IsEnabled { get; set; } = true;
641	
642	    public CameraDemoInputSystem(CameraDemoScreen screen)
643	    {
644	        _screen = screen;
645	        _previous = Keyboard.GetState();
646	    }
647	
648	    public void Update(GameState state)
649	    {
650	        if (!IsEnabled) return;
651	        var current = Keyboard.GetState();
652	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
653	
654	        if (Pressed(Keys.D0) || Pressed(Keys.NumPad0)) _screen.SetMode(CameraDemoScreen.Mode.Follow);
655	        if (Pressed(Keys.D1) || Pressed(Keys.NumPad1)) _screen.SetMode(CameraDemoScreen.Mode.FixedTL);
656	        if (Pressed(Keys.D2) || Pressed(Keys.NumPad2)) _screen.SetMode(CameraDemoScreen.Mode.FixedTR);
657	        if (Pressed(Keys.D3) || Pressed(Keys.NumPad3)) _screen.SetMode(CameraDemoScreen.Mode.FixedBR);
658	        if (Pressed(Keys.D4) || Pressed(Keys.NumPad4)) _screen.SetMode(CameraDemoScreen.Mode.FixedBL);
659	        if (Pressed(Keys.D5) || Pressed(Keys.NumPad5)) _screen.SetMode(CameraDemoScreen.Mode.FixedCenter);
660	        if (Pressed(Keys.L)) _screen.ToggleLerp();
661	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
662	
663	        _previous = current;
664	    }
665	
666	    public void Dispose() => GC.SuppressFinalize(this);
667	}
668	
669	/// While the red dot is the active camera target (follow mode), zooms the camera
670	/// out a little in proportion to how far its center lags behind the dot. The lag
671	/// is the world-space distance between the ball and the resolved camera position;
672	/// it grows when the dot moves faster than the camera can ease toward it, and when
673	/// the dot pushes past the camera-bounds edges (where the clamp pins the camera).
674	///
675	/// Lag maps linearly to a zoom reduction, capped at <see cref="MaxZoomOut"/>, and
676	/// the applied zoom is eased toward that target so it widens and recovers smoothly.
677	/// When no ball is the active target (fixed modes), the target zoom is 1, so the
678	/// view eases back to its default. This only writes <c>Camera.Zoom</c>, so it never
679	/// competes with <see cref="CameraFollowSystem"/>'s ownership of <c>Camera.Position</c>.
680	public class CameraLagZoomSystem : ISystem<GameState>
681	{
682	    // Lag (in world units) at which the zoom-out reaches its full MaxZoomOut. Sized
683	    // for this demo's boundary/camera-bounds geometry — at a corner the clamp holds
684	    // the camera ~110px behind the dot, comfortably inside this ceiling.
685	    private const float MaxLag = 150f;
686	    // Largest zoom reduction; 0.18 means the camera widens to at most 0.82× — "a little".
687	    private const float MaxZoomOut = 0.18f;
688	    // Exponential easing rate for the applied zoom, matched to the smooth-lerp feel.
689	    private const float ZoomDamping = 6f;
690	
691	    private readonly MonoDreams.Component.Camera _camera;
692	    private readonly EntitySet _activeBallTargets;
693	    private float _currentZoom = 1f;
694	
695	    public bool IsEnabled { get; set; } = true;
696	
697	    public CameraLagZoomSystem(World world, MonoDreams.Component.Camera camera)
698	    {
699	        _camera = camera;
700	        // The ball only carries CameraFollowTargetComponent while in follow mode, so
701	        // this set is non-empty exactly when the dot is the camera target.
702	        _activeBallTargets = world.GetEntities()
703	            .With<PlayerBallTag>()
704	            .With<CameraFollowTargetComponent>()
705	            .With<TransformComponent>()
706	            .AsSet();
707	    }
708	
709	    public void Update(GameState state)
710	    {
711	        if (!IsEnabled) return;
712	
713	        var targetZoom = 1f;
714	        foreach (var entity in _activeBallTargets.GetEntities())
715	        {
716	            if (!entity.Get<CameraFollowTargetComponent>().IsActive) continue;
717	            var lag = (entity.Get<TransformComponent>().Position - _camera.Position).Length();
718	            var t = MathHelper.Clamp(lag / MaxLag, 0f, 1f);
719	            targetZoom = 1f - t * MaxZoomOut;
720	            break;
721	        }
722	
723	        var smooth = 1f - (float)Math.Exp(-ZoomDamping * state.Time);
724	        _currentZoom = MathHelper.Lerp(_currentZoom, targetZoom, smooth);
725	        _camera.Zoom = _currentZoom;
726	    }
727	
728	    public void Dispose()
729	    {
730	        _activeBallTargets.Dispose();
731	        GC.SuppressFinalize(this);
732	    }
733	}
