using Microsoft.Xna.Framework;

namespace MonoDreams.Component;

public class CameraFollowTargetComponent
{
    public float DampingX { get; set; } = 5.0f;
    public float DampingY { get; set; } = 5.0f;
    public float MaxDistanceX { get; set; } = 100.0f;
    public float MaxDistanceY { get; set; } = 100.0f;
    public bool IsActive { get; set; } = true;

    /// <summary>
    /// Optional world-space rectangle the camera position is clamped to. When set,
    /// <see cref="MonoDreams.System.Camera.CameraFollowSystem"/> keeps the resolved
    /// camera position inside these bounds, so the camera tracks the target but never
    /// scrolls past the rectangle's edges (e.g. to keep the view within a level).
    /// When null the camera follows freely.
    /// </summary>
    public Rectangle? Bounds { get; set; } = null;
}

