32	    public Game1(string[]? args = null)
33	    {
34	        _headless = HeadlessOptions.Parse(args);
35	
36	        _graphics = new GraphicsDeviceManager(this);
37	        Content.RootDirectory = "Content";
38	        IsMouseVisible = false;
39	        _graphics.GraphicsProfile = GraphicsProfile.HiDef;
40	        // Headless still renders at full virtual resolution into a real backbuffer —
41	        // the window is just hidden off-screen and never relied on for presentation.
42	        // The render path (and its memory behaviour) is exercised exactly as in a
43	        // visible run, which is the whole point: a 1×1 window would make the captured
44	        // frame meaningless. See issue #28 and the debug-block premises.
45	        _graphics.PreferredBackBufferWidth = VirtualWidth;
46	        _graphics.PreferredBackBufferHeight = VirtualHeight;
47	        if (_headless.Enabled)
48	        {
49	            _graphics.SynchronizeWithVerticalRetrace = false;
50	            IsFixedTimeStep = false;
51	        }
52	        else
53	        {
54	            _graphics.SynchronizeWithVerticalRetrace = true;
55	            IsFixedTimeStep = true;
56	        }
