72	    protected override void Initialize()
73	    {
74	        var debugDir = global::System.Environment.GetEnvironmentVariable("MONODREAMS_DEBUG_DIR")
75	            ?? global::System.IO.Path.Combine(global::System.AppDomain.CurrentDomain.BaseDirectory, "debug");
76	        Logger.Initialize(debugDir);
77	
78	        // Project-wide dark navy theme for all MonoDreams demo screens.
79	        FinalDrawSystem.ClearColor = SproutPalette.DarkBg;
80	
81	        if (_headless.Enabled)
82	        {
83	            // Hide the window off-screen; the GL context (and its backbuffer) stay live
84	            // so Draw renders real frames we read back to PNG.
85	            Window.Position = new Point(-2000, -2000);
86	            _screenshotCapture = new ScreenshotCaptureSystem(GraphicsDevice, captureIntervalSeconds: 0f, debugDir);
