/// Renders one draw set into a render target with the given view transform.
private void RenderPass(RenderTarget2D target, EntitySet drawList, Matrix transformMatrix)
{
    graphicsDevice.SetRenderTarget(target);
    graphicsDevice.Clear(Color.Transparent);

    // Sort ALL entities by LayerDepth (stable sort preserves order for same depth)
    var entities = drawList.GetEntities().ToArray();
    var sortedEntities = entities
        .Select((entity, index) => (entity, index, dc: entity.Get<DrawComponent>()))
        .Where(x => x.dc.Type != DrawElementType.Mesh || x.dc.HasValidMesh)
        .OrderBy(x => x.dc.LayerDepth)
        .ThenBy(x => x.index) // Stable sort
        .ToList();

    if (sortedEntities.Count > 0)
        RenderInterleaved(sortedEntities, transformMatrix);
}

/// Draws the already-rendered minimap texture into its destination box on the
/// currently-bound HUD target. Downscaled, so LinearClamp for a smooth result.
private void CompositeMinimap(MinimapView m)
{
    spriteBatch.Begin(
        SpriteSortMode.Deferred, BlendState.AlphaBlend, SamplerState.LinearClamp,
        DepthStencilState.None, RasterizerState.CullNone);
    spriteBatch.Draw(m.Target, m.Destination, Color.White);
    spriteBatch.End();
}

