74	    /// Parses the periodic "Heap sample: ... bytes=N" log lines and asserts the live
75	    /// managed heap stays flat across the run — i.e. a retained-object leak (like the
76	    /// per-frame EntitySet leak from #27) is absent. The first <paramref name="skipSamples"/>
77	    /// samples are dropped as JIT/content warmup; the remainder must stay within
78	    /// <paramref name="maxGrowthRatio"/> of the smallest post-warmup sample.
79	    public void AssertHeapFlat(double maxGrowthRatio = 1.5, int skipSamples = 1)
80	    {
81	        var samples = GetHeapSamples();
82	        Assert.True(samples.Count > skipSamples + 1,
83	            $"Expected more than {skipSamples + 1} heap samples, found {samples.Count}.");
84	
85	        var stable = samples.Skip(skipSamples).ToList();
86	        var min = stable.Min();
87	        var max = stable.Max();
88	        Assert.True(min > 0, "Heap samples must be positive.");
89	        Assert.True(max <= min * maxGrowthRatio,
90	            $"Live heap grew from {min} to {max} bytes across the run (ratio {(double)max / min:F2} > {maxGrowthRatio}). " +
91	            "This looks like a leak — a static scene should hold a flat live heap.");
92	    }
93	
94	    private static readonly Regex HeapSampleRegex = new(@"Heap sample:.*bytes=(\d+)", RegexOptions.Compiled);
95	
96	    public List<long> GetHeapSamples()
97	    {
98	        var result = new List<long>();
99	        foreach (var line in LogLines)
100	        {
101	            var m = HeapSampleRegex.Match(line);
102	            if (m.Success && long.TryParse(m.Groups[1].Value, out var bytes))
103	                result.Add(bytes);
104	        }
105	        return result;
106	    }
